const dadosAtuais = msg.payload.list[0];

const temperatura = Number(dadosAtuais.main.temp);
const descricao = dadosAtuais.weather[0].description;

let volumeChuvaMM = 0;
if (dadosAtuais.rain && typeof dadosAtuais.rain["3h"] !== 'undefined') {
    volumeChuvaMM = Number(dadosAtuais.rain["3h"]);
}

let probChuva = 0;
if (typeof dadosAtuais.pop !== 'undefined') {
    probChuva = Number(dadosAtuais.pop) * 100;
}

// 1. Pega a umidade real vinda da memória global (Wokwi Circuito 2)
// Se não houver dado ainda, assume 0% (seco) para proteger a planta
let umidadeSolo = global.get("umidade_atual") || 0;

// Configurações de limite do seu sistema
const MAX_LITROS = 2.5;       // Carga máxima de água se o solo estiver em 0%
const UMIDADE_ALVO = 60;      // Meta de umidade do solo
const AREA_VASO_M2 = 0.4;             

let necessidadeIdealLitros = 0;

// 🧠 2. CÁLCULO VARIÁVEL E PROPORCIONAL DA NECESSIDADE HÍDRICA
if (umidadeSolo < UMIDADE_ALVO) {
    // Calcula a porcentagem de "secura" do solo (vai de 0.0 a 1.0)
    let fatorSecura = (UMIDADE_ALVO - umidadeSolo) / UMIDADE_ALVO;

    // A necessidade de água escala proporcionalmente à secura
    necessidadeIdealLitros = MAX_LITROS * fatorSecura;
} else {
    necessidadeIdealLitros = 0; // Solo já atingiu ou passou a meta de 60%
}

// 3. Subtrai a contribuição da chuva prevista (rega complementar)
let aguaChuvaLitros = volumeChuvaMM * AREA_VASO_M2;
let aguaNecessariaL = necessidadeIdealLitros - aguaChuvaLitros;

// 4. Integração Preditiva: Se a chance de chuva for > 70%, corta a rega pela metade
if (probChuva > 70 && aguaNecessariaL > 0) {
    aguaNecessariaL = aguaNecessariaL * 0.5;
}

// 5. Trava de segurança para evitar volumes negativos
if (aguaNecessariaL < 0) {
    aguaNecessariaL = 0;
}

// Arredonda para duas casas decimais (ex: 1.34)
aguaNecessariaL = Math.round(aguaNecessariaL * 100) / 100;

// ========================================================
// PREPARAÇÃO DOS DADOS PARA AS SAÍDAS
// ========================================================
let msgClima = { measurement: "condicao_climatica", payload: { descricao, temperatura } };
let msgVolume = { measurement: "volume_chuva", payload: { milimetros: volumeChuvaMM } };
let msgProbabilidade = { measurement: "probabilidade_chuva", payload: { porcentagem: probChuva } };
let msgCalculoLiters = { measurement: "calculo_rega", payload: { litros_calculados: aguaNecessariaL } };

let msgStatus = {
    measurement: "status_bomba",
    payload: { estado: aguaNecessariaL > 0 ? 1 : 0 }
};

let msgMQTT = { payload: aguaNecessariaL > 0 ? aguaNecessariaL.toString() : "OFF" };

return [
    [msgClima],         // Saída 1 -> InfluxDB
    [msgVolume],        // Saída 2 -> InfluxDB
    [msgProbabilidade], // Saída 3 -> InfluxDB
    [msgCalculoLiters], // Saída 4 -> InfluxDB
    [msgStatus],        // Saída 5 -> InfluxDB
    [msgMQTT]           // Saída 6 -> MQTT Out para o Wokwi
];

let litros = Number(msg.payload);

// 1. Mensagem para guardar o histórico de litros consumidos
let msgHistorico = {
    measurement: "historico_rega_efetuada",
    payload: { litros_gastos: litros }
};

// 2. Mensagem para atualizar o status da bomba para DESLIGADA (0)
let msgStatus = {
    measurement: "status_bomba",
    payload: { estado: 0 }
};

// Retorna as duas mensagens sequencialmente para o nó do InfluxDB
return [[msgHistorico, msgStatus]];

// Recebe o texto do Wokwi e converte para número
let umidadeSolo = Number(msg.payload);

// 🚨 A MÁGICA DA MEMÓRIA: Salva o valor para a função principal ler
global.set("umidade_atual", umidadeSolo);

// Prepara para salvar no InfluxDB
msg.measurement = "umidade_solo";
msg.payload = { 
    porcentagem: umidadeSolo 
};

return msg;
